package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

final class SecurityIncidentsAcceptance {
 static String api(String id){return "/api/openservice/security-incidents/"+id+"/response";}
 static String record(String id){return "/api/now/table/security_incident/"+id;}
 static String tasks(String id){return "/api/openservice/records/security_incident/"+id+"/work-tasks";}
 static String reviews(String id){return "/api/openservice/records/security_incident/"+id+"/approvals";}
 static void enroll(WorkflowSupport h,String group,int revision,boolean active)throws Exception{result(h.json("POST","/api/openservice/security/teams",map("group_id",group,"revision",revision,"active",active),auth("admin")));}
 static Map<String,Object> intake(String group){return map("group_id",group,"summary","Restricted security event <script>","description","Private suspicious activity","key",Values.id());}
 static String[] setup(WorkflowSupport h)throws Exception{
  for(String name:List.of("SecAnalyst","SecReviewer","SecOther"))h.account(name,"agent");h.account("SecReader","reader");String group=h.add("sys_user_group").get("sys_id").toString();for(String name:List.of("SecAnalyst","SecReviewer","SecReader"))RecordScopesAcceptance.member(h,group,FieldDispatchAcceptance.uid(h,name),true);enroll(h,group,0,true);String id=result(h.json("POST","/api/openservice/security/intake",intake(group),auth("SecAnalyst"))).get("sys_id").toString();String file=result(h.request("POST","/api/now/attachment/file?table_name=security_incident&table_sys_id="+id+"&file_name=security-proof.txt","Evidence captured".getBytes(),"text/plain",auth("SecAnalyst"))).get("sys_id").toString();String ci=h.add("cmdb_ci").get("sys_id").toString();return new String[]{id,group,file,ci};
 }
 static Map<String,Object> body(WorkflowSupport h,String id,String operation)throws Exception{var p=get(h,api(id),"SecAnalyst");return map("operation",operation,"revision",p.get("revision"),"record_revision",Integer.parseInt(object(p.get("record")).get("sys_mod_count").toString()));}
 static Map<String,Object> analysis(WorkflowSupport h,String[] ids,String classification)throws Exception{var b=body(h,ids[0],"analyze");b.putAll(map("classification",classification,"findings","Investigated suspicious activity <script>","assets",List.of(ids[3]),"evidence",List.of(ids[2])));return b;}
 static Map<String,Object> send(WorkflowSupport h,String id,Map<String,Object> b)throws Exception{return result(h.json("POST",api(id),b,auth("SecAnalyst")));}
 static void state(WorkflowSupport h,String id,String state,int expected)throws Exception{var r=h.json("PATCH",record(id),map("state",state),auth("SecAnalyst"));assertEquals(expected,r.statusCode(),html(r));}
 static Map<String,Object> taskBody(WorkflowSupport h,String id,String operation)throws Exception{var p=get(h,tasks(id),"SecAnalyst");var tasks=objects(p.get("tasks"));var b=map("operation",operation,"record_revision",Integer.parseInt(object(p.get("parent")).get("sys_mod_count").toString()),"revision",operation.equals("create")?object(p.get("plan")).get("revision"):tasks.getLast().get("revision"));if(!operation.equals("create"))b.put("task_id",tasks.getLast().get("task_id"));return b;}
 static void work(WorkflowSupport h,String id,String group,boolean required)throws Exception{var b=taskBody(h,id,"create");b.putAll(map("summary","Contain affected device","details","Perform and verify isolation using the approved endpoint tool","group_id",group,"required",required,"predecessors",List.of()));result(h.json("POST",tasks(id),b,auth("SecAnalyst")));}
 static void complete(WorkflowSupport h,String id)throws Exception{result(h.json("POST",tasks(id),taskBody(h,id,"claim"),auth("SecAnalyst")));var b=taskBody(h,id,"complete");b.put("outcome","Device isolation verified through authorized endpoint console");result(h.json("POST",tasks(id),b,auth("SecAnalyst")));}
 static void closure(WorkflowSupport h,String id,String code)throws Exception{var b=body(h,id,"review");b.putAll(map("code",code,"notes","Containment and recovery outcomes reviewed <script>"));send(h,id,b);}
 static void approve(WorkflowSupport h,String id)throws Exception{String a=result(h.json("POST",reviews(id),map("expected_revision",Integer.parseInt(get(h,record(id),"SecAnalyst").get("sys_mod_count").toString()),"approver","SecReviewer","target_state","closed","reason","Review investigation, response and closure evidence"),auth("SecAnalyst"))).get("approval_id").toString();result(h.json("POST",reviews(id)+"/"+a+"/decision",map("decision","approved","comment","Response evidence independently reviewed"),auth("SecReviewer")));}
 static void run(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(false,get(h,api(id),"SecAnalyst").get("current"));state(h,id,"contain",409);send(h,id,analysis(h,ids,"confirmed"));state(h,id,"contain",200);state(h,id,"review",409);work(h,id,ids[1],true);state(h,id,"review",409);complete(h,id);work(h,id,ids[1],true);state(h,id,"review",409);complete(h,id);state(h,id,"review",200);approve(h,id);state(h,id,"closed",409);closure(h,id,"resolved");state(h,id,"closed",409);approve(h,id);state(h,id,"closed",200);result(h.json("PATCH",record(id),map(),auth("SecAnalyst")));new Store(h.environment);assertEquals(2,objects(get(h,api(id),"SecReviewer").get("history")).size());assertEquals(true,get(h,api(id),"SecAnalyst").get("current"));state(h,id,"analysis",200);assertEquals(false,get(h,api(id),"SecAnalyst").get("current"));state(h,id,"contain",409);send(h,id,analysis(h,ids,"confirmed"));assertFalse(object(get(h,api(id),"SecAnalyst").get("document")).containsKey("closure"));state(h,id,"contain",200);state(h,id,"review",200);closure(h,id,"resolved");approve(h,id);state(h,id,"closed",200);assertEquals(204,h.json("DELETE",record(id),map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_security_document WHERE record_id=?",id));assertEquals(0,db.count("SELECT COUNT(*) FROM os_security_case WHERE record_id=?",id));}
 }
 static void authority(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var b=analysis(h,ids,"confirmed");send(h,id,b);for(String user:List.of("SecOther","SecReader")){assertEquals(user.equals("SecOther")?404:403,h.get(api(id),auth(user)).statusCode());assertEquals(404,h.get("/api/now/attachment/"+ids[2]+"/file",auth(user)).statusCode());}assertFalse(html(h.get("/api/now/table/security_incident",auth("SecOther"))).contains(id));assertEquals("0",object(get(h,"/api/now/stats/security_incident?sysparm_count=true","SecOther").get("stats")).get("count"));assertTrue(objects(parsed(h.get("/export/security_incident",auth("SecOther"))).get("result")).isEmpty());assertFalse(html(h.get("/audit",auth("SecOther"))).contains("Private suspicious activity"));assertFalse(html(h.get("/api/openservice/work-tasks",auth("SecOther"))).contains(id));assertEquals(403,h.json("POST","/api/openservice/security/intake",intake(ids[1]),auth("SecOther")).statusCode());assertEquals(403,h.json("POST","/api/openservice/security/teams",map("group_id",ids[1],"revision",1,"active",true),auth("SecAnalyst")).statusCode());
  assertEquals(200,h.get("/api/openservice/security",auth("SecAnalyst")).statusCode());assertEquals(200,h.get("/api/openservice/security",auth("SecOther")).statusCode());RecordScopesAcceptance.member(h,ids[1],FieldDispatchAcceptance.uid(h,"SecAnalyst"),false);assertEquals(404,h.get(api(id),auth("SecAnalyst")).statusCode());RecordScopesAcceptance.member(h,ids[1],FieldDispatchAcceptance.uid(h,"SecAnalyst"),true);enroll(h,ids[1],1,false);assertEquals(403,h.json("POST","/api/openservice/security/intake",intake(ids[1]),auth("SecAnalyst")).statusCode());assertEquals(200,h.get("/api/openservice/security",auth("SecAnalyst")).statusCode());assertEquals(404,h.get(api(id),auth("SecAnalyst")).statusCode());assertEquals(200,h.get(api(id),auth("admin")).statusCode());enroll(h,ids[1],2,true);assertEquals(200,h.get(api(id),auth("SecAnalyst")).statusCode());
  ProblemInvestigationsAcceptance.access(h,"cmdb_ci",ids[3],"private",FieldDispatchAcceptance.uid(h,"SecOther"));var p=get(h,api(id),"SecAnalyst");assertFalse(JSON.writeValueAsString(p).contains(ids[3]));assertEquals("Restricted or unavailable configuration item",objects(object(p.get("document")).get("assets")).getFirst().get("short_description"));
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"security_incident");}for(String mode:List.of("hidden","write","table","reader")){var schema=new LinkedHashMap<>(original);if(mode.equals("reader")){var roles=new LinkedHashMap<>(object(original.get("record_roles")));roles.put("read",List.of("admin","agent","reader"));schema.put("record_roles",roles);}else if(mode.equals("table")){var roles=new LinkedHashMap<>(object(original.get("record_roles")));roles.put("update",List.of("admin"));schema.put("record_roles",roles);}else schema.put("field_rules",map("description",map("type","string",mode.equals("hidden")?"read_roles":"write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"security_incident",schema);try{if(mode.equals("hidden"))assertEquals(403,h.get(api(id),auth("SecAnalyst")).statusCode());else if(mode.equals("reader"))assertEquals(404,h.get(record(id),auth("SecReader")).statusCode());else{assertEquals(false,get(h,api(id),"SecAnalyst").get("can_edit"));assertEquals(403,h.json("POST",api(id),b,auth("SecAnalyst")).statusCode());}}finally{ReferencePickerAcceptance.writeSchema(h,"security_incident",original);}}
  Map<String,Object> ciSchema;try(var db=h.store.open()){ciSchema=Service.schema(db,"cmdb_ci");}var hiddenCi=new LinkedHashMap<>(ciSchema);var ciRoles=new LinkedHashMap<>(object(ciSchema.getOrDefault("record_roles",map())));ciRoles.put("read",List.of("admin"));hiddenCi.put("record_roles",ciRoles);ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",hiddenCi);try{assertEquals(List.of(),get(h,api(id),"SecAnalyst").get("asset_choices"));}finally{ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",ciSchema);}
  var allowed=new LinkedHashMap<>(original);allowed.put("field_rules",map("description",map("type","string","write_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"security_incident",allowed);try{assertEquals(true,get(h,api(id),"SecAnalyst").get("can_edit"));}finally{ReferencePickerAcceptance.writeSchema(h,"security_incident",original);}
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(401,h.get("/api/openservice/security",null).statusCode());assertEquals(403,h.get("/api/openservice/security",auth("SecReader")).statusCode());assertEquals(405,h.json("PUT",api(id),map(),auth("SecAnalyst")).statusCode());assertEquals(400,h.get(api(id)+"?q=x",auth("SecAnalyst")).statusCode());assertEquals(409,h.json("POST","/api/now/table/security_incident",map("short_description","Bypassed intake"),auth("admin")).statusCode());assertEquals(409,h.json("POST","/api/openservice/import/security_incident?dry_run=false",List.of(map("sys_id",Values.id(),"short_description","Bypassed import","state","analysis")),auth("admin")).statusCode());
  for(var change:List.of(map("extra",1),map("group_id",""),map("key","bad"),map("summary",""))){var b=intake(ids[1]);b.putAll(change);assertEquals(400,h.json("POST","/api/openservice/security/intake",b,auth("SecAnalyst")).statusCode());}for(var change:List.of(map("active","true"),map("extra",1))){var b=map("group_id",ids[1],"revision",1,"active",true);b.putAll(change);assertEquals(400,h.json("POST","/api/openservice/security/teams",b,auth("admin")).statusCode());}assertEquals(409,h.json("POST","/api/openservice/security/teams",map("group_id",ids[1],"revision",0,"active",true),auth("admin")).statusCode());
  for(var change:List.of(map("operation","other"),map("extra",1),map("classification","other"),map("findings",""),map("assets","wrong"),map("assets",Collections.nCopies(21,ids[3])),map("assets",List.of(ids[3],ids[3])),map("evidence",List.of()),map("evidence",List.of(ids[2],ids[2])))){var b=analysis(h,ids,"confirmed");b.putAll(change);assertEquals(400,h.json("POST",api(id),b,auth("SecAnalyst")).statusCode());}for(String field:List.of("revision","record_revision")){var b=analysis(h,ids,"confirmed");b.put(field,999);assertEquals(409,h.json("POST",api(id),b,auth("SecAnalyst")).statusCode());}
  send(h,id,analysis(h,ids,"false_positive"));state(h,id,"contain",409);state(h,id,"review",200);assertEquals(409,h.json("POST",api(id),analysis(h,ids,"confirmed"),auth("SecAnalyst")).statusCode());var wrong=body(h,id,"review");wrong.putAll(map("code","resolved","notes","Review"));assertEquals(400,h.json("POST",api(id),wrong,auth("SecAnalyst")).statusCode());closure(h,id,"false_positive");work(h,id,ids[1],false);approve(h,id);state(h,id,"closed",409);var cancel=taskBody(h,id,"cancel");cancel.put("reason","No response required after false-positive review");result(h.json("POST",tasks(id),cancel,auth("SecAnalyst")));state(h,id,"closed",200);
 }
 static void evidence(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];send(h,id,analysis(h,ids,"confirmed"));String access="/api/openservice/attachment-access/"+ids[2];var held=AttachmentHoldsAcceptance.result(h,access);result(h.json("POST",access,map("held",true,"review",held.get("review"),"reason","Withhold evidence pending inspection"),auth("admin")));assertEquals(false,objects(object(get(h,api(id),"SecAnalyst").get("document")).get("evidence")).getFirst().get("available"));state(h,id,"contain",409);held=AttachmentHoldsAcceptance.result(h,access);result(h.json("POST",access,map("held",false,"review",held.get("review"),"reason","Evidence inspection complete"),auth("admin")));state(h,id,"contain",200);work(h,id,ids[1],true);var waive=taskBody(h,id,"waive");waive.put("reason","Waiver is not actual containment evidence");result(h.json("POST",tasks(id),waive,auth("admin")));state(h,id,"review",409);work(h,id,ids[1],true);complete(h,id);state(h,id,"review",200);closure(h,id,"resolved");var cancel=taskBody(h,id,"cancel");cancel.put("task_id",objects(get(h,tasks(id),"SecAnalyst").get("tasks")).getFirst().get("task_id"));cancel.put("revision",1);cancel.put("reason","Close waived pending work");result(h.json("POST",tasks(id),cancel,auth("SecAnalyst")));Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,"security_incident");}var altered=new LinkedHashMap<>(schema);altered.put("transition_rules",map());ReferencePickerAcceptance.writeSchema(h,"security_incident",altered);try{state(h,id,"closed",409);approve(h,id);RecordScopesAcceptance.member(h,ids[1],FieldDispatchAcceptance.uid(h,"SecReviewer"),false);state(h,id,"closed",409);RecordScopesAcceptance.member(h,ids[1],FieldDispatchAcceptance.uid(h,"SecReviewer"),true);state(h,id,"closed",200);}finally{ReferencePickerAcceptance.writeSchema(h,"security_incident",schema);}
  state(h,id,"analysis",200);send(h,id,analysis(h,ids,"confirmed"));try(var db=h.store.open()){db.update("UPDATE os_attachment SET content=? WHERE sys_id=?","Changed evidence".getBytes(),ids[2]);db.connection.commit();}state(h,id,"contain",409);
 }
 static void concurrency(WorkflowSupport h)throws Exception{
  var ids=setup(h);var intake=intake(ids[1]);String first=result(h.json("POST","/api/openservice/security/intake",intake,auth("SecAnalyst"))).get("sys_id").toString();assertEquals(first,result(h.json("POST","/api/openservice/security/intake",intake,auth("SecAnalyst"))).get("sys_id"));intake.put("summary","Conflicting retry");assertEquals(409,h.json("POST","/api/openservice/security/intake",intake,auth("SecAnalyst")).statusCode());String id=ids[0];var b=analysis(h,ids,"confirmed");try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{start.await();return h.json("POST",api(id),b,auth("SecAnalyst")).statusCode();});var c=pool.submit(()->{start.await();return h.json("POST",api(id),b,auth("SecAnalyst")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),c.get()));}try(var db=h.store.open()){var detail=db.one("SELECT detail FROM os_security_document WHERE record_id=?",id).get("detail");for(int n=2;n<100;n++)db.update("INSERT INTO os_security_document(record_id,revision,detail) VALUES(?,?,?)",id,n,JSON.writeValueAsString(detail));db.connection.commit();}send(h,id,analysis(h,ids,"confirmed"));assertEquals(100,objects(get(h,api(id),"SecAnalyst").get("history")).size());assertEquals(400,h.json("POST",api(id),analysis(h,ids,"confirmed"),auth("SecAnalyst")).statusCode());
 }
}
